from pathlib import Path
import hashlib,base64,gzip,json
root=Path('tach-xep-pdf-v2.3.2')
p=root/'TachXepTrangPDF.cs'
raw=p.read_bytes()
expected_base='7fffc4bd0e880ccc246eb0b789970c82fcf83e80e6c240bcc845758377bdf317'
if hashlib.sha256(raw).hexdigest()!=expected_base:
    raise SystemExit('unexpected v2.4.2 reconstructed source before v2.4.3 patch')
lines=raw.decode('utf-8-sig').replace('\r\n','\n').splitlines(True)
ops=json.loads(gzip.decompress(base64.b64decode('')).decode('utf-8'))
offset=0
for tag,i1,i2,repl in ops:
    a=i1+offset; b=i2+offset
    lines[a:b]=repl
    offset += len(repl)-(i2-i1)
out=''.join(lines).encode('utf-8-sig')
expected_final='fceb99ece38533a4dec08b5dff034c9b902e38b58b2cf9cd6c9d8ad56c48f4ad'
if hashlib.sha256(out).hexdigest()!=expected_final:
    raise SystemExit('v2.4.3 source patch checksum mismatch')
p.write_bytes(out)

launcher=root/'launcher.cpp'
ls=launcher.read_text(encoding='utf-8-sig')
ls2=ls.replace('2.4.2','2.4.3')
if ls2==ls: raise SystemExit('launcher 2.4.2 marker missing')
launcher.write_text(ls2,encoding='utf-8-sig')

csproj=root/'TachXepTrangPDF.csproj'
cs=csproj.read_text(encoding='utf-8-sig')
cs2=cs.replace('2.4.2','2.4.3')
if cs2==cs: raise SystemExit('csproj 2.4.2 marker missing')
csproj.write_text(cs2,encoding='utf-8-sig')

reg=root/'regression_test.py'
rt=reg.read_text(encoding='utf-8')
extra='''\n# v2.4.3 protected interaction regressions\nsrc=Path(__file__).with_name("TachXepTrangPDF.cs").read_text(encoding="utf-8-sig")\nfor marker in ["AppVersion = \\\"2.4.3\\\"","TrackBar _zoom","_zoom.Minimum = 50","_zoom.Maximum = 250","EnsureListSelectionVisible","ShowImmediatePreviewFromThumbnail","SemaphoreSlim _previewRenderGate","PdfSession _previewPdf","CHỈNH ĐƯỜNG CẮT","TrackBar _manualCutSlider","Áp dụng đường cắt","ApplyManualCut","GetSelectedSourceFace","Lên 1","Xuống 1","Lên đầu","Xuống cuối","RunWorkflowSmoke"]:\n    assert marker in src, marker\nassert "_cut.Enabled = !busy && !_isSplit" not in src\nassert "inner.Panel2Collapsed = true" not in src\nprint("REGRESSION_INTERACTION_V243_OK")\n'''
if 'REGRESSION_INTERACTION_V243_OK' not in rt:
    reg.write_text(rt+extra,encoding='utf-8')
print('PATCH_V243_DIRECT_DIFF_OK')
